/**
 * Séries da razão polegar-indicador lidas do painel de depuração em duas
 * gravações de tela do maintainer (2026-10-27): só números, nenhuma imagem.
 * Cada par é [tempo em ms, razão] e aparece quando o painel mostrou um valor
 * novo (a webcam entrega cerca de 15 quadros novos por segundo); `null` é mão
 * fora do quadro. A leitura é manual, por reconhecimento de dígitos, e pode ter
 * erros pontuais; leituras acima de 2,5 foram descartadas.
 */
export type Sample = readonly [timeMs: number, ratio: number | null]

